function g({registerIndicator:y,nulls:b}){y({id:"oa-iii",name:"Intraday Intensity Index (III)",category:"Volume",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:100,step:1,tooltip:"Smoothing period for the intensity index."},{key:"cumulative",type:"boolean",label:"Cumulative Mode",default:!1,tooltip:"Accumulate intensity values for trend analysis."}],plots:[{key:"iii",type:"line",title:"III",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,s){const l=Math.max(1,Math.min(100,Math.floor(Number(s.period)||14))),I=s.cumulative===!0,r=new Array(o.length).fill(NaN),c=new Array(l).fill(NaN);let t=0,n=0,m=0;for(let i=0;i<o.length;i++){const e=o[i],a=Number.isFinite(e.close)?e.close:0,p=Number.isFinite(e.high)?e.high:a,d=Number.isFinite(e.low)?e.low:a,N=Math.max(Number.isFinite(e.volume)?e.volume:0,1),f=p-d,u=(f>0?(2*a-p-d)/f:0)*N,h=c[t];Number.isFinite(h)&&(n-=h),n+=u,c[t]=u,t=(t+1)%l;const v=n/l;m+=u,r[i]=I?m:v}return{iii:b(r)}}})}export{g as default};
